import{_ as s,o as a,c as t,a6 as n}from"./chunks/framework.ZMCvXf1_.js";const u=JSON.parse('{"title":"SQL Terminal","description":"","frontmatter":{},"headers":[],"relativePath":"guide/database/terminal.md","filePath":"guide/database/terminal.md"}'),i={name:"guide/database/terminal.md"};function o(r,e,l,d,c,h){return a(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="sql-terminal" tabindex="-1">SQL Terminal <a class="header-anchor" href="#sql-terminal" aria-label="Permalink to “SQL Terminal”">​</a></h1><h2 id="what-it-is" tabindex="-1">What It Is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to “What It Is”">​</a></h2><p>The SQL terminal is an interactive REPL built into noorm. Run queries against your database without leaving the tool or switching to another client.</p><p>Debugging a change? Check if that INSERT worked. Exploring a table structure? Run a quick SELECT. The terminal keeps you in flow while you work.</p><h2 id="launching-the-terminal" tabindex="-1">Launching the Terminal <a class="header-anchor" href="#launching-the-terminal" aria-label="Permalink to “Launching the Terminal”">​</a></h2><p>Press <code>Shift+Q</code> from anywhere in the TUI. The terminal is a global shortcut, not an entry on the Database menu, so there is no <code>[d]</code> then <code>[t]</code> path to it. On the Database screen, <code>t</code> is teardown.</p><p>From a shell, launch straight into it:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sql</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repl</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # active config</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sql</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # a specific config</span></span></code></pre></div><p><code>noorm sql repl</code> opens the same TUI screen, so everything on this page applies to both. It needs an interactive terminal and refuses to run under <code>--yes</code> or <code>NOORM_YES</code>; for scripted SQL use <code>noorm sql query &quot;SELECT 1&quot;</code> or <code>noorm sql query -f query.sql</code> instead.</p><p>The terminal connects to your <a href="/guide/environments/configs.html">active configuration</a> automatically.</p><h2 id="the-interface" tabindex="-1">The Interface <a class="header-anchor" href="#the-interface" aria-label="Permalink to “The Interface”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>┌─ SQL Terminal ──────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                                                             │</span></span>
<span class="line"><span>│  &gt; SELECT * FROM users LIMIT 3;                             │</span></span>
<span class="line"><span>│                                                             │</span></span>
<span class="line"><span>│  ┌────┬─────────┬─────────────────┬─────────────────────┐   │</span></span>
<span class="line"><span>│  │ id │ name    │ email           │ created_at          │   │</span></span>
<span class="line"><span>│  ├────┼─────────┼─────────────────┼─────────────────────┤   │</span></span>
<span class="line"><span>│  │  1 │ Alice   │ alice@email.com │ 2024-01-15 09:30:00 │   │</span></span>
<span class="line"><span>│  │  2 │ Bob     │ bob@email.com   │ 2024-01-16 14:22:00 │   │</span></span>
<span class="line"><span>│  │  3 │ Charlie │ charlie@co.com  │ 2024-01-17 11:45:00 │   │</span></span>
<span class="line"><span>│  └────┴─────────┴─────────────────┴─────────────────────┘   │</span></span>
<span class="line"><span>│                                                             │</span></span>
<span class="line"><span>│  3 rows (12ms)                                              │</span></span>
<span class="line"><span>│                                                             │</span></span>
<span class="line"><span>│  &gt; _                                                        │</span></span>
<span class="line"><span>│                                                             │</span></span>
<span class="line"><span>│  [Shift+Tab] Edit mode  [Enter] Execute  [Shift+Enter] New  │</span></span>
<span class="line"><span>│  [h] History   [Esc] Clear                                  │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────────┘</span></span></code></pre></div><p>Type your SQL at the <code>&gt;</code> prompt and press Enter to execute. The prompt changes to <code>[EDIT]&gt;</code> in edit mode, where Enter inserts a newline instead of running the query.</p><h2 id="what-you-are-allowed-to-run" tabindex="-1">What You Are Allowed to Run <a class="header-anchor" href="#what-you-are-allowed-to-run" aria-label="Permalink to “What You Are Allowed to Run”">​</a></h2><p>Before anything reaches the database, noorm classifies the statement and checks that class against the <a href="/guide/environments/configs.html">config&#39;s access role</a>:</p><table tabindex="0"><thead><tr><th>Class</th><th>Permission</th><th><code>viewer</code></th><th><code>operator</code></th><th><code>admin</code></th></tr></thead><tbody><tr><td>Reads (<code>SELECT</code>, <code>SHOW</code>, <code>DESCRIBE</code>)</td><td><code>sql:read</code></td><td>Yes</td><td>Yes</td><td>Yes</td></tr><tr><td>Writes (<code>INSERT</code>, <code>UPDATE</code>, <code>DELETE</code>, <code>MERGE</code>)</td><td><code>sql:write</code></td><td>No</td><td>Yes</td><td>Yes</td></tr><tr><td>Everything else</td><td><code>sql:ddl</code></td><td>No</td><td>No</td><td>Yes</td></tr></tbody></table><p><code>sql:ddl</code> is the catch-all, not a DDL-keyword list. <code>CREATE</code>/<code>ALTER</code>/<code>DROP</code>/<code>TRUNCATE</code>/<code>GRANT</code>/<code>REVOKE</code>/<code>SET</code>, <code>EXEC</code>/<code>CALL</code>, and anything the classifier cannot make sense of all land there. Unrecognized input fails closed, on the reasoning that a statement nobody can classify could do anything.</p><p>Classification looks past the outer keyword, which matters more than it sounds:</p><ul><li>A statement is parsed, not pattern-matched, and the <strong>highest</strong> class anywhere in the tree wins. <code>WITH t AS (DELETE FROM logs ...) SELECT * FROM t</code> is a write, not a read.</li><li><code>EXPLAIN</code> takes the class of the statement it wraps, because <code>EXPLAIN ANALYZE</code> executes that statement. <code>EXPLAIN (ANALYZE) DELETE FROM t</code> is a write.</li><li><code>SELECT ... INTO</code> creates a table or writes a file, so it classifies as <code>sql:ddl</code> rather than a read.</li><li>A <code>SELECT</code> calling a side-effecting or filesystem builtin (<code>pg_terminate_backend</code>, <code>setval</code>, <code>pg_read_file</code>, and similar) is raised to <code>sql:write</code>, which is the lowest class a <code>viewer</code> cannot reach.</li><li>Multi-statement input takes the highest class present, so one <code>DROP</code> after a semicolon governs the whole submission.</li></ul><p>The denylist behind that last rule covers known-dangerous builtins, not every function that could have a side effect. It stops casual and accidental writes on a <code>viewer</code> config; it is not a sandbox for a determined adversary.</p><h2 id="running-queries" tabindex="-1">Running Queries <a class="header-anchor" href="#running-queries" aria-label="Permalink to “Running Queries”">​</a></h2><p>The terminal runs any SQL your database understands, subject to the access role above:</p><p><strong>SELECT queries</strong> return formatted tables with timing:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; SELECT id, email FROM users WHERE active = true LIMIT 5;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>┌────┬────────────────────┐</span></span>
<span class="line"><span>│ id │ email              │</span></span>
<span class="line"><span>├────┼────────────────────┤</span></span>
<span class="line"><span>│  1 │ alice@example.com  │</span></span>
<span class="line"><span>│  2 │ bob@example.com    │</span></span>
<span class="line"><span>└────┴────────────────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2 rows (8ms)</span></span></code></pre></div><p><strong>INSERT, UPDATE, DELETE</strong> report affected rows:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; UPDATE users SET last_login = NOW() WHERE id = 1;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1 row affected (5ms)</span></span></code></pre></div><p><strong>DDL statements</strong> (CREATE, ALTER, DROP) work too, on an <code>admin</code>-role config:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; CREATE INDEX users_email_idx ON users(email);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>OK (42ms)</span></span></code></pre></div><h2 id="stopping-a-query-that-will-not-come-back" tabindex="-1">Stopping a Query That Will Not Come Back <a class="header-anchor" href="#stopping-a-query-that-will-not-come-back" aria-label="Permalink to “Stopping a Query That Will Not Come Back”">​</a></h2><p><code>Escape</code> while a query is running gives the terminal back. What that does to the database depends on the dialect, and the terminal says which one happened:</p><table tabindex="0"><thead><tr><th>Dialect</th><th>On <code>Escape</code></th><th>What you see</th></tr></thead><tbody><tr><td>PostgreSQL</td><td><code>pg_cancel_backend</code> on a second connection</td><td><code>Cancelled. The server was asked to stop the query.</code></td></tr><tr><td>MySQL</td><td><code>KILL QUERY</code> on a second connection</td><td><code>Cancelled. The server was asked to stop the query.</code></td></tr><tr><td>SQL Server</td><td>nothing reaches the server</td><td><code>Stopped waiting. The query may still be running on the server.</code></td></tr><tr><td>SQLite</td><td>nothing reaches the server</td><td><code>Stopped waiting. The query may still be running on the server.</code></td></tr></tbody></table><p>The difference is not cosmetic. On the bottom two rows the query keeps running to completion, holding locks and burning CPU, and the only thing that changed is that noorm stopped listening for the answer. Kill it from the server side if it matters.</p><p>SQL Server is a limitation of the driver layer rather than of the database: tedious exposes a per-request cancel, but Kysely&#39;s MSSQL dialect owns the request object and never hands it out. SQLite has no second connection to interrupt the first from.</p><p><code>Escape</code> also works while the terminal is still connecting, which is what a network problem looks like before a query ever runs.</p><h2 id="result-formatting" tabindex="-1">Result Formatting <a class="header-anchor" href="#result-formatting" aria-label="Permalink to “Result Formatting”">​</a></h2><p>Results display in a formatted table with column alignment:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>┌─────┬────────────────────┬────────┬───────────────────────┐</span></span>
<span class="line"><span>│ id  │ email              │ name   │ created_at            │</span></span>
<span class="line"><span>├─────┼────────────────────┼────────┼───────────────────────┤</span></span>
<span class="line"><span>│ 1   │ alice@example.com  │ Alice  │ 2024-01-15T10:30:00Z  │</span></span>
<span class="line"><span>│ 2   │ bob@example.com    │ Bob    │ 2024-01-15T11:45:00Z  │</span></span>
<span class="line"><span>└─────┴────────────────────┴────────┴───────────────────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2 rows (15ms)</span></span></code></pre></div><p>Long values are truncated with an ellipsis to fit the column. There is no per-cell detail view, so to read a value in full, re-run the query selecting fewer columns.</p><p>Once a query returns rows, press <code>Tab</code> to move into the results table. From there:</p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>↑</code> / <code>↓</code></td><td>Navigate rows</td></tr><tr><td><code>/</code></td><td>Filter rows</td></tr><tr><td><code>s</code></td><td>Sort by a column</td></tr><tr><td><code>c</code></td><td>Clear the filter and sort</td></tr><tr><td><code>Tab</code> or <code>Esc</code></td><td>Return to the query input</td></tr></tbody></table><p>Errors display inline with the original query:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; SELECT * FROM nonexistent;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Error: relation &quot;nonexistent&quot; does not exist</span></span></code></pre></div><h2 id="query-history" tabindex="-1">Query History <a class="header-anchor" href="#query-history" aria-label="Permalink to “Query History”">​</a></h2><p>Every query you run is saved. Browse and re-execute past queries without retyping.</p><h3 id="browsing-history" tabindex="-1">Browsing History <a class="header-anchor" href="#browsing-history" aria-label="Permalink to “Browsing History”">​</a></h3><p>Press <code>h</code> to open the history viewer. The input must be empty, so clear the prompt first:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>┌─ Query History ─────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                                                             │</span></span>
<span class="line"><span>│  1. SELECT * FROM users LIMIT 10           12ms  ✓  1h ago  │</span></span>
<span class="line"><span>│  2. UPDATE users SET active = true...       5ms  ✓  2h ago  │</span></span>
<span class="line"><span>│  3. SELECT * FROM nonexistent               -    ✗  2h ago  │</span></span>
<span class="line"><span>│  4. INSERT INTO logs (msg) VALUES...        8ms  ✓  3h ago  │</span></span>
<span class="line"><span>│                                                             │</span></span>
<span class="line"><span>│  [r] Re-run  [Enter] View result  [c] Clear  [↑/↓] Navigate │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────────┘</span></span></code></pre></div><ul><li><code>✓</code> indicates successful queries</li><li><code>✗</code> indicates failed queries</li><li><code>r</code> sends the selected query back to the terminal, pre-filled and ready to edit before you run it</li><li><code>Enter</code> opens the stored results for that entry</li></ul><p>The history viewer has no search. To find an old query, scroll with the arrow keys.</p><h3 id="viewing-saved-results" tabindex="-1">Viewing Saved Results <a class="header-anchor" href="#viewing-saved-results" aria-label="Permalink to “Viewing Saved Results”">​</a></h3><p>Select a history entry and press <code>Enter</code> to view the full results from when the query ran. Results are stored gzipped, so you can review query output even after the data has changed.</p><p>Only queries that returned rows have stored results. Pressing <code>Enter</code> on a failed entry shows its error message instead, and on a row-less entry it tells you there is nothing stored.</p><h2 id="writing-multi-line-queries" tabindex="-1">Writing Multi-Line Queries <a class="header-anchor" href="#writing-multi-line-queries" aria-label="Permalink to “Writing Multi-Line Queries”">​</a></h2><p>The terminal has no tab completion. <code>Tab</code> inserts four spaces, so you can indent a query by hand.</p><p>There are two ways to write across several lines. <code>Shift+Enter</code> inserts a newline without running anything. For a longer statement, press <code>Shift+Tab</code> to enter edit mode, where plain <code>Enter</code> becomes a newline and the prompt changes to <code>[EDIT]&gt;</code>. Press <code>Shift+Tab</code> again to leave edit mode and get Enter-to-execute back.</p><h2 id="keyboard-shortcuts" tabindex="-1">Keyboard Shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to “Keyboard Shortcuts”">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>Enter</code></td><td>Execute query (insert a newline in edit mode)</td></tr><tr><td><code>Shift+Enter</code></td><td>Insert a newline</td></tr><tr><td><code>Shift+Tab</code></td><td>Toggle edit mode</td></tr><tr><td><code>Tab</code></td><td>Insert four spaces, or move between the query and the results table once a query has returned rows</td></tr><tr><td><code>Up</code> / <code>Down</code></td><td>Navigate command history when the input is empty, otherwise move the cursor</td></tr><tr><td><code>Left</code> / <code>Right</code></td><td>Move the cursor</td></tr><tr><td><code>Escape</code></td><td>Stop a running query or a connect in progress; otherwise clear the input, and on an empty input leave the terminal</td></tr><tr><td><code>h</code></td><td>Open the history viewer (empty input only)</td></tr></tbody></table><h2 id="clearing-history" tabindex="-1">Clearing History <a class="header-anchor" href="#clearing-history" aria-label="Permalink to “Clearing History”">​</a></h2><p>Open the history viewer with <code>h</code>, then press <code>c</code> for the clear menu:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>┌─ Clear History ─────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                                                             │</span></span>
<span class="line"><span>│  1. Clear last 3 months                                     │</span></span>
<span class="line"><span>│  2. Clear all history                                       │</span></span>
<span class="line"><span>│                                                             │</span></span>
<span class="line"><span>│  History: 47 entries, 2.3 MB stored                         │</span></span>
<span class="line"><span>│                                                             │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────────┘</span></span></code></pre></div><p>&quot;Clear last 3 months&quot; removes entries older than three months and keeps the rest. Either option deletes the stored result files along with their history entries. <code>noorm sql clear</code> does the same job from a shell.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to “Tips”">​</a></h2><p><strong>Always use LIMIT</strong> when exploring unfamiliar tables. A table with millions of rows will slow down your terminal.</p><p><strong>Preview before modifying</strong> - Run a SELECT with your WHERE clause before executing UPDATE or DELETE:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; SELECT id, email FROM users WHERE last_login &lt; &#39;2023-01-01&#39;;</span></span>
<span class="line"><span>-- Review the results</span></span>
<span class="line"><span>&gt; DELETE FROM users WHERE last_login &lt; &#39;2023-01-01&#39;;</span></span></code></pre></div><p><strong>History is not encrypted</strong> - Query text sits in plain JSON at <code>.noorm/state/history/&lt;config&gt;.json</code>, and returned rows sit gzipped beside it in <code>.noorm/state/history/&lt;config&gt;/</code>. Neither is encrypted, unlike <code>state.enc</code>. Both are written owner-only (<code>0600</code>, in a <code>0700</code> directory), but anything a <code>SELECT</code> pulled out of a credentials or PII table is readable by your user account. Avoid running queries that contain passwords or API keys, and clear the history after one slips through.</p><h2 id="what-s-next" tabindex="-1">What&#39;s Next? <a class="header-anchor" href="#what-s-next" aria-label="Permalink to “What&#39;s Next?”">​</a></h2><ul><li><a href="/guide/database/explore.html">Schema Explorer</a> - Browse tables, views, and other database objects</li><li><a href="/guide/environments/configs.html">Configs</a> - Switch between different databases</li><li><a href="/guide/sql-files/execution.html">Execution</a> - Run SQL files with change detection</li></ul>`,68)])])}const g=s(i,[["render",o]]);export{u as __pageData,g as default};
